#!/usr/bin/env bash
# setup_linux_netns.sh - Generated by PS-007 Network Creator
# Run with: sudo bash setup_linux_netns.sh
set -e

echo '[+] Enabling IPv6 forwarding...'
sysctl -w net.ipv6.conf.all.forwarding=1

echo '[+] Creating Linux Bridge br-iot0...'
ip link add name br-iot0 type bridge || true
ip link set br-iot0 up
ip -6 addr add 2001:db8:1::1/64 dev br-iot0 || true

echo '[+] Setting up ns-mon...'
ip netns add ns-mon || true
ip link add veth-mon type veth peer name veth-br-mon || true
ip link set veth-mon netns ns-mon
ip link set veth-br-mon master br-iot0
ip link set veth-br-mon up
ip netns exec ns-mon ip link set lo up
ip netns exec ns-mon ip link set veth-mon up
ip netns exec ns-mon ip -6 addr add 2001:db8:1::2/64 dev veth-mon || true

echo '[+] Setting up ns-iot1...'
ip netns add ns-iot1 || true
ip link add veth-iot1 type veth peer name veth-br-iot1 || true
ip link set veth-iot1 netns ns-iot1
ip link set veth-br-iot1 master br-iot0
ip link set veth-br-iot1 up
ip netns exec ns-iot1 ip link set lo up
ip netns exec ns-iot1 ip link set veth-iot1 up
ip netns exec ns-iot1 ip -6 addr add 2001:db8:1::101/64 dev veth-iot1 || true

echo '[+] Setting up ns-iot2...'
ip netns add ns-iot2 || true
ip link add veth-iot2 type veth peer name veth-br-iot2 || true
ip link set veth-iot2 netns ns-iot2
ip link set veth-br-iot2 master br-iot0
ip link set veth-br-iot2 up
ip netns exec ns-iot2 ip link set lo up
ip netns exec ns-iot2 ip link set veth-iot2 up
ip netns exec ns-iot2 ip -6 addr add 2001:db8:1::102/64 dev veth-iot2 || true

echo '[+] Setting up ns-iot3...'
ip netns add ns-iot3 || true
ip link add veth-iot3 type veth peer name veth-br-iot3 || true
ip link set veth-iot3 netns ns-iot3
ip link set veth-br-iot3 master br-iot0
ip link set veth-br-iot3 up
ip netns exec ns-iot3 ip link set lo up
ip netns exec ns-iot3 ip link set veth-iot3 up
ip netns exec ns-iot3 ip -6 addr add 2001:db8:1::103/64 dev veth-iot3 || true

echo '[+] Setting up ns-iot4...'
ip netns add ns-iot4 || true
ip link add veth-iot4 type veth peer name veth-br-iot4 || true
ip link set veth-iot4 netns ns-iot4
ip link set veth-br-iot4 master br-iot0
ip link set veth-br-iot4 up
ip netns exec ns-iot4 ip link set lo up
ip netns exec ns-iot4 ip link set veth-iot4 up
ip netns exec ns-iot4 ip -6 addr add 2001:db8:1::104/64 dev veth-iot4 || true

echo '[+] Setting up ns-iot5...'
ip netns add ns-iot5 || true
ip link add veth-iot5 type veth peer name veth-br-iot5 || true
ip link set veth-iot5 netns ns-iot5
ip link set veth-br-iot5 master br-iot0
ip link set veth-br-iot5 up
ip netns exec ns-iot5 ip link set lo up
ip netns exec ns-iot5 ip link set veth-iot5 up
ip netns exec ns-iot5 ip -6 addr add 2001:db8:1::105/64 dev veth-iot5 || true

echo '[+] Setting up ns-attacker...'
ip netns add ns-attacker || true
ip link add veth-atk type veth peer name veth-br-atk || true
ip link set veth-atk netns ns-attacker
ip link set veth-br-atk master br-iot0
ip link set veth-br-atk up
ip netns exec ns-attacker ip link set lo up
ip netns exec ns-attacker ip link set veth-atk up
ip netns exec ns-attacker ip -6 addr add 2001:db8:1::bad:1/64 dev veth-atk || true

echo '[SUCCESS] IPv6 IoT Isolated Virtual Network Created!'
echo '[*] Bridge: br-iot0 with IPv6: 2001:db8:1::1/64'
echo '[*] Namespaces: ns-mon, ns-iot1..ns-iot5, ns-attacker'
echo '[*] To run Scapy monitor in monitor namespace: sudo ip netns exec ns-mon python3 backend/app.py'
